def monotonic(l: list):
    """Return True if list elements are monotonically increasing or decreasing."""
    if len(l) <= 2:
        return True

    increasing = l[1] >= l[0]
    decreasing = l[1] <= l[0]

    for i in range(2, len(l)):
        if increasing and l[i] < l[i-1]:
            return False
        if decreasing and l[i] > l[i-1]:
            return False

    return True
